-- DATU BĀZES VISPĀRĪGS APRAKSTS

-- Dota poliklīnikas datu bāze. Tajā ir informācija par mediķiem,
-- pacientiem, to diagnozēm, kā arī vizītēm. Pacientiem ir arī dažādas
-- apkalpošanas klases. Tāpat jebkuram cilvēkam var būt norādīta dzimšanas
-- valsts. Mediķiem var būt norādīta arī nodaļa un specialitāte.
-- Katrai specialitātei ir norādīta profesija.


-- TABULU IZVEIDE

CREATE TABLE CILVEKI (
    PERS_KODS    VARCHAR2(5 CHAR) NOT NULL,
    VARDS        VARCHAR2(150 CHAR) NOT NULL,
    UZVARDS      VARCHAR2(150 CHAR) NOT NULL,
    DZ_DATUMS    DATE,
    DZIMS_VALSTS VARCHAR2(2 CHAR)
);

COMMENT ON TABLE CILVEKI IS
    'Visu cilvēku saraksts.
Katrs cilvēks var būt gan mediķis, gan pacients, bet var arī nebūt nekas no tā.';

COMMENT ON COLUMN CILVEKI.PERS_KODS IS
    'Cilvēka personas kods (cilvēka unikāls identifikators)';

COMMENT ON COLUMN CILVEKI.VARDS IS
    'Cilvēka vārds';

COMMENT ON COLUMN CILVEKI.UZVARDS IS
    'Cilvēka uzvārds';

COMMENT ON COLUMN CILVEKI.DZ_DATUMS IS
    'Cilvēka dzimšanas datums';

COMMENT ON COLUMN CILVEKI.DZIMS_VALSTS IS
    'Dzimšanas valsts';

ALTER TABLE CILVEKI ADD CONSTRAINT CILVEKI_PK PRIMARY KEY ( PERS_KODS );

CREATE TABLE DIAGNOZES (
    KODS      VARCHAR2(5 CHAR) NOT NULL,
    NOSAUKUMS VARCHAR2(200 CHAR) NOT NULL
);

COMMENT ON TABLE DIAGNOZES IS
    'Diagnožu klasifikators';

COMMENT ON COLUMN DIAGNOZES.KODS IS
    'Diagnozes kods (unikāls identifikators)';

COMMENT ON COLUMN DIAGNOZES.NOSAUKUMS IS
    'Diagnozes nosaukums';

ALTER TABLE DIAGNOZES ADD CONSTRAINT DIAGNOZES_PK PRIMARY KEY ( KODS );

CREATE TABLE KLASES (
    KODS      NUMBER(3) NOT NULL,
    NOSAUKUMS VARCHAR2(150 CHAR) NOT NULL
);

COMMENT ON TABLE KLASES IS
    'Pacientu apkalpošanas (servisa līmeņa) klašu saraksts';

COMMENT ON COLUMN KLASES.KODS IS
    'Apkalpošanas klases kods (unikāls identifikators)';

COMMENT ON COLUMN KLASES.NOSAUKUMS IS
    'Apkalpošanas klases nosaukums';

ALTER TABLE KLASES ADD CONSTRAINT KLASE_PK PRIMARY KEY ( KODS );

CREATE TABLE MEDIKI (
    NUMURS             NUMBER(5) NOT NULL,
    ALGA               NUMBER(10, 2) NOT NULL,
    PIENEMTS           DATE NOT NULL,
    NODALAS_NUMURS     NUMBER(3),
    CILVEKI_PERS_KODS  VARCHAR2(5 CHAR) NOT NULL,
    SPECIALITATES_KODS NUMBER(3)
);

COMMENT ON TABLE MEDIKI IS
    'Visu mediķu saraksts.
Katrs mediķis ir vai nu ārsts, vai nu medmāsa, bet ne abi.';

COMMENT ON COLUMN MEDIKI.NUMURS IS
    'Mediķa numurs (unikāls identifikators)';

COMMENT ON COLUMN MEDIKI.ALGA IS
    'Mediķa mēneša pamatalga (EUR)';

COMMENT ON COLUMN MEDIKI.PIENEMTS IS
    'Mediķa darbā pieņemšanas datums';

CREATE UNIQUE INDEX MEDIKI__IDX ON
    MEDIKI (
        CILVEKI_PERS_KODS
    ASC );

ALTER TABLE MEDIKI ADD CONSTRAINT MEDIKI_PK PRIMARY KEY ( NUMURS );

CREATE TABLE NODALAS (
    NUMURS    NUMBER(3) NOT NULL,
    NOSAUKUMS VARCHAR2(150 CHAR) NOT NULL
);

COMMENT ON TABLE NODALAS IS
    'Poliklīnikā esošo nodaļu saraksts';

COMMENT ON COLUMN NODALAS.NUMURS IS
    'Nodaļas numurs (unikāls identifikators)';

COMMENT ON COLUMN NODALAS.NOSAUKUMS IS
    'Nodaļas nosaukums';

ALTER TABLE NODALAS ADD CONSTRAINT NODALAS_PK PRIMARY KEY ( NUMURS );

CREATE TABLE PACIENTI (
    NUMURS            NUMBER(5) NOT NULL,
    CILVEKI_PERS_KODS VARCHAR2(5 CHAR) NOT NULL,
    KLASE_KODS        NUMBER(3)
);

COMMENT ON TABLE PACIENTI IS
    'Visu pacientu saraksts';

COMMENT ON COLUMN PACIENTI.NUMURS IS
    'Pacienta numurs (unikāls identifikators)';

CREATE UNIQUE INDEX PACIENTI__IDX ON
    PACIENTI (
        CILVEKI_PERS_KODS
    ASC );

ALTER TABLE PACIENTI ADD CONSTRAINT PACIENTI_PK PRIMARY KEY ( NUMURS );

CREATE TABLE PACIENTI_DIAGNOZES (
    PACIENTI_NUMURS NUMBER(5) NOT NULL,
    DIAGNOZES_KODS  VARCHAR2(5 CHAR) NOT NULL,
    DATUMS          DATE
);

COMMENT ON COLUMN PACIENTI_DIAGNOZES.DATUMS IS
    'Diagnozes pirmreizējās uzstādīšanas datums';

ALTER TABLE PACIENTI_DIAGNOZES ADD CONSTRAINT PACIENTI_DIAGNOZES_PK PRIMARY KEY ( PACIENTI_NUMURS,
                                                                                  DIAGNOZES_KODS );

CREATE TABLE PROFESIJAS (
    KODS      VARCHAR2(3 CHAR) NOT NULL,
    NOSAUKUMS VARCHAR2(150 CHAR) NOT NULL
);

COMMENT ON TABLE PROFESIJAS IS
    'Medicīnas darbinieku (mediķu) profesiju saraksts';

COMMENT ON COLUMN PROFESIJAS.KODS IS
    'Profesijas kods (unikāls identifikators)';

COMMENT ON COLUMN PROFESIJAS.NOSAUKUMS IS
    'Profesijas nosaukums';

ALTER TABLE PROFESIJAS ADD CONSTRAINT PROFESIJAS_PK PRIMARY KEY ( KODS );

CREATE TABLE SPECIALITATES (
    KODS            NUMBER(3) NOT NULL,
    NOSAUKUMS       VARCHAR2(150 CHAR) NOT NULL,
    PROFESIJAS_KODS VARCHAR2(3 CHAR) NOT NULL
);

COMMENT ON TABLE SPECIALITATES IS
    'Mediķu specialitāšu saraksts';

COMMENT ON COLUMN SPECIALITATES.KODS IS
    'Mediķa specialitātes kods (specialitātes unikāls identifikators)';

COMMENT ON COLUMN SPECIALITATES.NOSAUKUMS IS
    'Specialitātes nosaukums';

ALTER TABLE SPECIALITATES ADD CONSTRAINT SPECIALITATES_PK PRIMARY KEY ( KODS );

CREATE TABLE VALSTIS (
    KODS      VARCHAR2(2 CHAR) NOT NULL,
    NOSAUKUMS VARCHAR2(150 CHAR) NOT NULL
);

COMMENT ON TABLE VALSTIS IS
    'Valstu saraksts';

COMMENT ON COLUMN VALSTIS.KODS IS
    'Valsts kods (unikāls identifikators)';

COMMENT ON COLUMN VALSTIS.NOSAUKUMS IS
    'Valsts nosaukums';

ALTER TABLE VALSTIS ADD CONSTRAINT VALSTIS_PK PRIMARY KEY ( KODS );

CREATE TABLE VIZITES (
    NUMURS          NUMBER(38) NOT NULL,
    DATUMS          DATE NOT NULL,
    ILGUMS          NUMBER(3) NOT NULL,
    MAKSA           NUMBER(10, 2) NOT NULL,
    PACIENTI_NUMURS NUMBER(5) NOT NULL,
    MEDIKI_NUMURS   NUMBER(5) NOT NULL
);

COMMENT ON COLUMN VIZITES.NUMURS IS
    'Vizītes numurs (unikāls identifikators)';

COMMENT ON COLUMN VIZITES.DATUMS IS
    'Vizītes datums';

COMMENT ON COLUMN VIZITES.ILGUMS IS
    'Vizītes ilgums minūtēs';

COMMENT ON COLUMN VIZITES.MAKSA IS
    'Pacienta samaksātā summa (EUR) par vizīti';

ALTER TABLE VIZITES ADD CONSTRAINT VIZITES_PK PRIMARY KEY ( NUMURS );

ALTER TABLE CILVEKI
    ADD CONSTRAINT CILVEKI_VALSTIS_FK FOREIGN KEY ( DZIMS_VALSTS )
        REFERENCES VALSTIS ( KODS )
            ON DELETE SET NULL;

ALTER TABLE MEDIKI
    ADD CONSTRAINT MEDIKI_CILVEKI_FK FOREIGN KEY ( CILVEKI_PERS_KODS )
        REFERENCES CILVEKI ( PERS_KODS );

ALTER TABLE MEDIKI
    ADD CONSTRAINT MEDIKI_NODALAS_FK FOREIGN KEY ( NODALAS_NUMURS )
        REFERENCES NODALAS ( NUMURS )
            ON DELETE SET NULL;

ALTER TABLE MEDIKI
    ADD CONSTRAINT MEDIKI_SPECIALITATES_FK FOREIGN KEY ( SPECIALITATES_KODS )
        REFERENCES SPECIALITATES ( KODS )
            ON DELETE SET NULL;

ALTER TABLE PACIENTI
    ADD CONSTRAINT PACIENTI_CILVEKI_FK FOREIGN KEY ( CILVEKI_PERS_KODS )
        REFERENCES CILVEKI ( PERS_KODS );

ALTER TABLE PACIENTI_DIAGNOZES
    ADD CONSTRAINT PACIENTI_DIAGN_DIAGNOZES_FK FOREIGN KEY ( DIAGNOZES_KODS )
        REFERENCES DIAGNOZES ( KODS );

ALTER TABLE PACIENTI_DIAGNOZES
    ADD CONSTRAINT PACIENTI_DIAGN_PACIENTI_FK FOREIGN KEY ( PACIENTI_NUMURS )
        REFERENCES PACIENTI ( NUMURS );

ALTER TABLE PACIENTI
    ADD CONSTRAINT PACIENTI_KLASE_FK FOREIGN KEY ( KLASE_KODS )
        REFERENCES KLASES ( KODS );

ALTER TABLE SPECIALITATES
    ADD CONSTRAINT SPECIALITATES_PROFESIJAS_FK FOREIGN KEY ( PROFESIJAS_KODS )
        REFERENCES PROFESIJAS ( KODS );

ALTER TABLE VIZITES
    ADD CONSTRAINT VIZITES_MEDIKI_FK FOREIGN KEY ( MEDIKI_NUMURS )
        REFERENCES MEDIKI ( NUMURS );

ALTER TABLE VIZITES
    ADD CONSTRAINT VIZITES_PACIENTI_FK FOREIGN KEY ( PACIENTI_NUMURS )
        REFERENCES PACIENTI ( NUMURS );

COMMIT;


