-- SKATU IZVEIDE

CREATE OR REPLACE VIEW MP1 AS
SELECT
    C1.PERS_KODS MEDIKIS, C2.PERS_KODS PACIENTS,
    SUM(V.ILGUMS) SUM_ILGUMS
FROM
    MEDIKI M
    JOIN CILVEKI C1 ON C1.PERS_KODS = M.CILVEKI_PERS_KODS
    JOIN VIZITES V ON V.MEDIKI_NUMURS = M.NUMURS
    JOIN PACIENTI P ON P.NUMURS = V.PACIENTI_NUMURS
    JOIN CILVEKI C2 ON C2.PERS_KODS = P.CILVEKI_PERS_KODS
GROUP BY C1.PERS_KODS, C2.PERS_KODS
ORDER BY SUM_ILGUMS DESC, MEDIKIS ASC;


CREATE OR REPLACE VIEW MP2 AS
SELECT
    C1.PERS_KODS MEDIKIS, C2.PERS_KODS PACIENTS,
    SUM(V.ILGUMS) SUM_ILGUMS, SUM(V.MAKSA) SUM_MAKSA,
    COUNT(*) VIZ_SKAITS
FROM
    MEDIKI M
    JOIN CILVEKI C1 ON C1.PERS_KODS = M.CILVEKI_PERS_KODS
    JOIN VIZITES V ON V.MEDIKI_NUMURS = M.NUMURS
    JOIN PACIENTI P ON P.NUMURS = V.PACIENTI_NUMURS
    JOIN CILVEKI C2 ON C2.PERS_KODS = P.CILVEKI_PERS_KODS
GROUP BY C1.PERS_KODS, C2.PERS_KODS
ORDER BY VIZ_SKAITS DESC, MEDIKIS ASC;


CREATE OR REPLACE VIEW MP3 AS
SELECT
    C1.PERS_KODS MEDIKIS, C2.PERS_KODS PACIENTS,
    EXTRACT(YEAR FROM V.DATUMS) GADS, SUM(V.MAKSA) SAMAKSA
FROM
    MEDIKI M
    JOIN CILVEKI C1 ON C1.PERS_KODS = M.CILVEKI_PERS_KODS
    JOIN VIZITES V ON V.MEDIKI_NUMURS = M.NUMURS
    JOIN PACIENTI P ON P.NUMURS = V.PACIENTI_NUMURS
    JOIN CILVEKI C2 ON C2.PERS_KODS = P.CILVEKI_PERS_KODS
GROUP BY C1.PERS_KODS, C2.PERS_KODS, EXTRACT(YEAR FROM V.DATUMS)
ORDER BY GADS, MEDIKIS, PACIENTS;


CREATE OR REPLACE VIEW NP1 AS
    SELECT
        N.NUMURS NODALA, C.PERS_KODS PACIENTS, V.MAKSA SAMAKSA
    FROM
        MEDIKI M
        JOIN NODALAS N ON N.NUMURS = M.NODALAS_NUMURS
        JOIN VIZITES V ON V.MEDIKI_NUMURS = M.NUMURS
        JOIN PACIENTI P ON P.NUMURS = V.PACIENTI_NUMURS
        JOIN CILVEKI C ON C.PERS_KODS = P.CILVEKI_PERS_KODS
    ORDER BY NODALA DESC, PACIENTS DESC, SAMAKSA DESC;


CREATE OR REPLACE VIEW NP2 AS
    SELECT
        N.NUMURS NODALA, S.KODS SPECIALITATE, 
        EXTRACT(YEAR FROM V.DATUMS) GADS, K.KODS KLASE,
        V.NUMURS VIZITE, V.MAKSA SAMAKSA
    FROM
        MEDIKI M
        JOIN NODALAS N ON N.NUMURS = M.NODALAS_NUMURS
        JOIN SPECIALITATES S ON S.KODS = M.SPECIALITATES_KODS
        JOIN VIZITES V ON V.MEDIKI_NUMURS = M.NUMURS
        JOIN PACIENTI P ON P.NUMURS = V.PACIENTI_NUMURS
        JOIN KLASES K ON K.KODS = P.KLASE_KODS
    ORDER BY
        NODALA DESC, SPECIALITATE DESC,
        GADS DESC, KLASE DESC, VIZITE DESC, SAMAKSA DESC;

COMMIT;

CREATE OR REPLACE VIEW PACIENTU_DIAGNOZES AS
SELECT
P.CILVEKI_PERS_KODS AS CPK,
C.VARDS AS CV,
C.UZVARDS AS CU,
PD.DIAGNOZES_KODS AS DK,
D.NOSAUKUMS AS DN,
PD.DATUMS AS PDD
FROM PACIENTI P
JOIN CILVEKI C ON C.PERS_KODS = P.CILVEKI_PERS_KODS
JOIN PACIENTI_DIAGNOZES PD ON P.NUMURS = PD.PACIENTI_NUMURS
JOIN DIAGNOZES D ON D.KODS = PD.DIAGNOZES_KODS
WHERE P.CILVEKI_PERS_KODS LIKE '%3'
ORDER BY P.CILVEKI_PERS_KODS ASC, PD.DIAGNOZES_KODS DESC;

CREATE OR REPLACE VIEW NODALAS_VALSTIS AS
SELECT
V.KODS AS VK,
V.NOSAUKUMS AS VN,
N.NUMURS AS NNU,
N.NOSAUKUMS AS NNO,
M.CILVEKI_PERS_KODS AS CPK,
C.VARDS AS CV,
C.UZVARDS AS CU,
M.NUMURS AS MN,
M.ALGA AS MA
FROM MEDIKI M
JOIN CILVEKI C ON C.PERS_KODS = M.CILVEKI_PERS_KODS
JOIN NODALAS N ON N.NUMURS = M.NODALAS_NUMURS
JOIN VALSTIS V ON V.KODS = C.DZIMS_VALSTS
WHERE M.NODALAS_NUMURS IS NOT NULL AND C.DZIMS_VALSTS IS NOT NULL
AND M.ALGA < 4821.90
ORDER BY V.KODS ASC, N.NUMURS DESC, M.CILVEKI_PERS_KODS ASC;

SELECT *
FROM MP1
PIVOT
(
    SUM(SUM_ILGUMS)
    FOR PACIENTS
    IN ('C004', 'C007', 'C009', 'C011')
)
WHERE MEDIKIS IN ('C001','C002','C003','C004','C005')
ORDER BY MEDIKIS ASC;

SELECT *
FROM NP1
PIVOT
(
SUM(SAMAKSA)
FOR NODALA
IN (2,5,6,7,8)
)
WHERE PACIENTS IN ('C004', 'C007', 'C009', 'C011')
ORDER BY PACIENTS ASC;

SELECT MEDIKIS, PACIENTS, SUM(SUM_MAKSA) AS SAMAKSA
FROM MP2
WHERE MEDIKIS LIKE '%3' AND PACIENTS LIKE '%5'
GROUP BY ROLLUP (MEDIKIS, PACIENTS)
ORDER BY MEDIKIS ASC, PACIENTS DESC;

SELECT NODALA, PACIENTS, SUM(SAMAKSA) AS SAMAKSA
FROM NP1
WHERE NODALA < 7 AND PACIENTS <> '%5_' AND SAMAKSA > 107.22
GROUP BY ROLLUP (NODALA, PACIENTS)
ORDER BY NODALA DESC, PACIENTS ASC;

SELECT 
    DECODE(PACIENTS, NULL, 'Visi pacienti', PACIENTS) PACIENTS,
    DECODE(MEDIKIS, NULL, 'Visi mediki', MEDIKIS) MEDIKIS,
    SUM(SUM_ILGUMS) ILGUMS
FROM MP2
WHERE (MEDIKIS LIKE '%7_' OR MEDIKIS LIKE '%2_') AND PACIENTS LIKE '%4'
GROUP BY CUBE(PACIENTS, MEDIKIS)
ORDER BY PACIENTS ASC, MEDIKIS DESC;

SELECT
DECODE (PACIENTS, NULL, 'Visi pacienti', PACIENTS) PACIENTS,
DECODE (NODALA, NULL, 'Visas nodalas', NODALA) NODALA,
SUM(SAMAKSA) SAMAKSA
FROM NP1
WHERE NODALA < 7 AND PACIENTS IN ('C003', 'C005', 'C006', 'C007')
GROUP BY CUBE(PACIENTS, NODALA)
ORDER BY PACIENTS DESC, NODALA DESC;

SELECT GADS, MEDIKIS, PACIENTS, SAMAKSA
FROM MP3
WHERE 
    GADS > 2020 
    AND (MEDIKIS LIKE '%1' OR MEDIKIS LIKE '%3') 
    AND PACIENTS LIKE '%5'
MODEL
    PARTITION BY (GADS)
    DIMENSION BY (MEDIKIS, PACIENTS)
    MEASURES (SAMAKSA)
    RULES (
        SAMAKSA[ANY, ANY] =
            CASE 
                WHEN CV(MEDIKIS) LIKE '%1' 
                    THEN SAMAKSA[CV(MEDIKIS), CV(PACIENTS)] * 10
                ELSE SAMAKSA[CV(MEDIKIS), CV(PACIENTS)]
            END,

        SAMAKSA[ANY, ANY] =
            CASE 
                WHEN CV(MEDIKIS) LIKE '%3' 
                    THEN SAMAKSA[CV(MEDIKIS), CV(PACIENTS)] * 100
                ELSE SAMAKSA[CV(MEDIKIS), CV(PACIENTS)]
            END
    )
ORDER BY GADS ASC, MEDIKIS ASC, PACIENTS DESC;

SELECT NODALA, GADS, SPECIALITATE, KLASE, VIZITE, SAMAKSA
FROM NP2
WHERE 
    GADS > 2020
    AND SPECIALITATE >= 200
    AND VIZITE > 978
    AND KLASE <> 3
MODEL
    PARTITION BY (NODALA)
    DIMENSION BY (GADS, SPECIALITATE, KLASE, VIZITE)
    MEASURES (SAMAKSA)
    RULES (
        SAMAKSA[ANY, ANY, 1, ANY] =
            CASE 
                WHEN CV(GADS) = 2022 
                THEN SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)] * 2
                ELSE SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)]
            END,

        SAMAKSA[ANY, ANY, ANY, ANY] =
            CASE 
                WHEN CV(GADS) = 2021 AND CV(SPECIALITATE) > 201
                THEN SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)] * 10
                ELSE SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)]
            END,

        SAMAKSA[ANY, ANY, ANY, ANY] =
            CASE 
                WHEN CV(GADS) = 2021 
                     AND CV(SPECIALITATE) < 201 
                     AND CV(KLASE) > 1
                THEN SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)] + 50
                ELSE SAMAKSA[CV(GADS), CV(SPECIALITATE), CV(KLASE), CV(VIZITE)]
            END
    )
ORDER BY NODALA ASC, GADS ASC, SPECIALITATE ASC, KLASE ASC, VIZITE ASC;

